γ = {0: {'a': {3, 4}}, 1: {'a': {5}}}
δ = {0: {'a': {6}, 'b': {7}}}
assert merge(γ, δ) == {0: {'a': {3, 4, 6}, 'b': {7}}, 1: {'a': {5}}}
```

